package io.github.x647368maker.atomicworkbench.config

import android.Manifest
import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import android.view.View
import android.widget.*
import androidx.appcompat.app.AppCompatActivity
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import java.util.concurrent.Executors

internal object UpdateSection {
    fun create(activity: AppCompatActivity): View {
        fun dp(n:Int)=(n*activity.resources.displayMetrics.density).toInt()
        val installed=UpdateCoordinator.installed(activity)
        val root=LinearLayout(activity).apply { orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(20),dp(16),dp(12)) }
        fun label(value:String)=TextView(activity).apply { text=value;textSize=14f;setTextColor(SettingsPalette.text(activity));setPadding(0,dp(8),0,dp(8)) }
        root.addView(label("在线更新 · ${installed.versionName} (${installed.longVersionCode})"))
        val channel=Spinner(activity)
        channel.adapter=ArrayAdapter(activity,android.R.layout.simple_spinner_dropdown_item,listOf("开发版（含稳定版）","仅稳定版"))
        channel.setSelection(if(UpdateCoordinator.channel(activity)==UpdatePolicy.Channel.DEV)0 else 1)
        root.addView(channel)
        channel.onItemSelectedListener=object:AdapterView.OnItemSelectedListener {
            override fun onNothingSelected(parent:AdapterView<*>?)=Unit
            override fun onItemSelected(parent:AdapterView<*>?,view:View?,position:Int,id:Long) {
                val selected=if(position==0)UpdatePolicy.Channel.DEV else UpdatePolicy.Channel.STABLE
                if(UpdateCoordinator.channel(activity)!=selected) UpdateCoordinator.setChannel(activity,selected)
            }
        }
        root.addView(Switch(activity).apply {
            text="启动应用时自动检查更新（正常每12小时一次）";isChecked=UpdateCoordinator.auto(activity)
            setOnCheckedChangeListener { _,enabled ->
                UpdateCoordinator.setAuto(activity,enabled)
                if(enabled) UpdateCoordinator.maybeCheck(activity) {
                    if(!activity.isDestroyed && !activity.isFinishing) Toast.makeText(activity,"发现可验证的新版本，请点击查看 / 安装新版本",Toast.LENGTH_LONG).show()
                }
                if(enabled && activity.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)
                    activity.requestPermissions(arrayOf(Manifest.permission.POST_NOTIFICATIONS),72)
            }
        })
        val status=label("默认开启低频检查（正常每12小时一次），可手动关闭；仅打开 App 时检查，不常驻后台。即使拒绝通知仍可在应用内查看更新。")
        root.addView(status)
        var release=UpdateCoordinator.available(activity)
        var disposed=false
        val worker=Executors.newSingleThreadExecutor()
        root.addOnAttachStateChangeListener(object:View.OnAttachStateChangeListener {
            override fun onViewAttachedToWindow(v:View)=Unit
            override fun onViewDetachedFromWindow(v:View) { disposed=true;worker.shutdownNow() }
        })
        val check=Button(activity).apply { text="检查更新" }
        val download=Button(activity).apply { text="查看 / 安装新版本";isEnabled=true }
        fun valid()=!disposed&&!activity.isDestroyed&&!activity.isFinishing
        fun showRelease(r:UpdateChecker.Release) {
            MaterialAlertDialogBuilder(activity).setTitle("台前调度 ${r.version}")
                .setMessage("版本码：${r.metadata.versionCode}\n大小：${String.format(java.util.Locale.ROOT,"%.1f",r.metadata.size/1048576.0)} MB\n\n"+r.notes.ifBlank { "发布者未填写变更说明" }+"\n\n下载后会校验 SHA-256、包名、版本和签名，再由系统请求确认安装。升级后请正常重启设备。")
                .setNegativeButton("稍后",null).setPositiveButton("下载并验证") { _,_ ->
                    check.isEnabled=false;download.isEnabled=false;status.text="下载并校验中…"
                    worker.execute {
                        val result=runCatching { UpdateInstaller.download(activity.applicationContext,r) }
                        activity.runOnUiThread {
                            if(!valid())return@runOnUiThread
                            check.isEnabled=true;download.isEnabled=true
                            result.onSuccess { file ->
                                status.text="校验通过，请在系统安装界面确认。"
                                if(!activity.packageManager.canRequestPackageInstalls()) {
                                    status.text="请允许此来源，返回后点击安装重试（已下载文件会复用）。"
                                    MaterialAlertDialogBuilder(activity).setTitle("允许安装更新")
                                        .setMessage("需要允许台前调度调用系统安装器。不会使用 Root 静默安装。")
                                        .setNegativeButton("取消",null).setPositiveButton("打开设置") { _,_ ->
                                            runCatching { activity.startActivity(Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.packageName))) }
                                        }.show()
                                } else runCatching { UpdateInstaller.install(activity,file,r) }.onFailure { status.text=it.message ?: "系统安装器不可用" }
                            }.onFailure { status.text="更新失败，可安全重试："+(it.message ?: "网络或校验失败") }
                        }
                    }
                }.show()
        }
        check.setOnClickListener {
            check.isEnabled=false;status.text="正在检查本项目发布…"
            worker.execute {
                val result=runCatching { UpdateCoordinator.check(activity.applicationContext) }
                activity.runOnUiThread {
                    if(!valid()) return@runOnUiThread
                    check.isEnabled=true
                    result.onSuccess { found ->
                        release=found;download.isEnabled=found!=null
                        status.text=if(found==null)"暂无可验证的更高版本。历史无校验元数据的版本会忽略。" else "发现 ${found.version}，版本码 ${found.metadata.versionCode}"
                        found?.let(::showRelease)
                    }.onFailure { status.text="检查失败，不影响工作区："+(it.message ?: "请稍后重试") }
                }
            }
        }
        download.setOnClickListener { release=UpdateCoordinator.available(activity); if(release==null) { check.performClick(); return@setOnClickListener }; release?.takeIf { UpdatePolicy.eligible(it.metadata,installed.longVersionCode,UpdateCoordinator.channel(activity)) }?.let(::showRelease) }
        for(button in listOf(check,download)) root.addView(button,LinearLayout.LayoutParams(-1,dp(52)))
        root.addView(Button(activity).apply { text="查看项目发布页面";setOnClickListener { openBrowser(activity,UpdateChecker.RELEASES_URL) } },LinearLayout.LayoutParams(-1,dp(52)))
        root.addView(label("更新后需要正常重启一次加载新版模块；不会清除工作组、固定应用或设置。"))
        return root
    }
    internal fun openBrowser(activity:AppCompatActivity,address:String) {
        runCatching { activity.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(UpdateChecker.requireHttps(address))).addCategory(Intent.CATEGORY_BROWSABLE)) }
            .onFailure { Toast.makeText(activity,"无法打开浏览器",Toast.LENGTH_LONG).show() }
    }
}

package io.github.x647368maker.atomicworkbench.config

import android.Manifest
import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import androidx.appcompat.app.AppCompatActivity
import java.util.concurrent.Executors

/** Lightweight default-on checks on app entry: 12h after success, 1h after failure. User can opt out. No background polling. */
internal object UpdateCoordinator {
    private val worker=Executors.newSingleThreadExecutor()
    @Volatile private var checking=false
    private fun prefs(c: Context)=c.getSharedPreferences("atomic_updates_v1",Context.MODE_PRIVATE)
    fun installed(c: Context)=c.packageManager.getPackageInfo(c.packageName,0)
    fun channel(c: Context): UpdatePolicy.Channel = runCatching {
        UpdatePolicy.Channel.valueOf(prefs(c).getString("channel",null) ?: if(installed(c).versionName.orEmpty().contains("-dev")) "DEV" else "STABLE")
    }.getOrDefault(UpdatePolicy.Channel.DEV)
    fun setChannel(c: Context,v: UpdatePolicy.Channel) { prefs(c).edit().putString("channel",v.name).putLong("last_check",0).apply() }
    fun auto(c: Context)=prefs(c).getBoolean("auto",true)
    fun setAuto(c: Context,v: Boolean) { prefs(c).edit().putBoolean("auto",v).putLong("last_check",0).apply() }
    fun available(c: Context): UpdateChecker.Release? = runCatching {
        val release=UpdateChecker.decode(prefs(c).getString("available",null) ?: return@runCatching null)
        release.takeIf { UpdatePolicy.eligible(it.metadata,installed(c).longVersionCode,channel(c)) }
    }.getOrNull()
    fun check(c: Context): UpdateChecker.Release? {
        val release=UpdateChecker.check(channel(c),installed(c).longVersionCode)
        prefs(c).edit().putString("available",release?.let(UpdateChecker::encode)).apply()
        return release
    }
    fun maybeCheck(activity: AppCompatActivity,changed: () -> Unit) {
        val p=prefs(activity);val code=installed(activity).longVersionCode
        val previous=p.getLong("seen_code",code)
        p.edit().putLong("seen_code",code).apply()
        if(previous<code) android.widget.Toast.makeText(activity,"已升级台前调度，请正常重启设备以加载新版 Vector 模块",android.widget.Toast.LENGTH_LONG).show()
        val now=System.currentTimeMillis()
        if(!UpdateCheckSchedule.due(auto(activity),checking,now,p.getLong("last_check",0),p.getBoolean("last_success",true))) return
        p.edit().putLong("last_check",now).apply();checking=true
        val app=activity.applicationContext
        worker.execute {
            val result=runCatching { check(app) }
            prefs(app).edit().putBoolean("last_success",result.isSuccess).apply()
            val release=result.getOrNull()
            checking=false
            if(release!=null) {
                runCatching { notify(app,release) }
                activity.runOnUiThread { if(!activity.isDestroyed&&!activity.isFinishing) changed() }
            }
        }
    }
    fun onNotificationPermission(c: Context) { if (!auto(c)) return; available(c)?.let { runCatching { notify(c,it) } } }
    private fun notify(c: Context,r: UpdateChecker.Release) {
        if(c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED) return
        val p=prefs(c);if(p.getLong("notified",0)>=r.metadata.versionCode) return
        val manager=c.getSystemService(NotificationManager::class.java)
        manager.createNotificationChannel(NotificationChannel("atomic_updates","台前调度更新",NotificationManager.IMPORTANCE_DEFAULT))
        val intent=Intent(c,MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_SINGLE_TOP).putExtra("stage_page","about")
        val pending=PendingIntent.getActivity(c,72,intent,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE)
        manager.notify(72,Notification.Builder(c,"atomic_updates").setSmallIcon(android.R.drawable.stat_sys_download_done)
            .setContentTitle("台前调度发现新版本").setContentText(r.version+" · 点击查看更新说明")
            .setContentIntent(pending).setAutoCancel(true).build())
        p.edit().putLong("notified",r.metadata.versionCode).apply()
    }
}

package io.github.x647368maker.atomicworkbench.config

import android.graphics.Color
import android.os.Bundle
import androidx.activity.OnBackPressedCallback
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowCompat
import androidx.core.view.WindowInsetsCompat
import androidx.core.view.WindowInsetsControllerCompat
import androidx.core.view.updatePadding
import io.github.x647368maker.atomicworkbench.icons.LauncherIconManager

class MainActivity : AppCompatActivity() {
    private lateinit var settings: StageSettingsScreen
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        supportActionBar?.hide()
        WindowCompat.setDecorFitsSystemWindows(window, false)
        window.statusBarColor = Color.TRANSPARENT
        window.navigationBarColor = Color.TRANSPARENT
        window.isNavigationBarContrastEnforced = false
        settings = StageSettingsScreen(this, SettingsRepository(this))
        WindowInsetsControllerCompat(window, window.decorView).apply {
            isAppearanceLightStatusBars = !settings.dark
            isAppearanceLightNavigationBars = !settings.dark
        }
        val root = settings.view
        ViewCompat.setOnApplyWindowInsetsListener(root) { view, insets ->
            val safe = insets.getInsets(WindowInsetsCompat.Type.systemBars() or WindowInsetsCompat.Type.displayCutout())
            val keyboard = insets.getInsets(WindowInsetsCompat.Type.ime())
            view.updatePadding(left = safe.left, top = safe.top, right = safe.right, bottom = maxOf(safe.bottom, keyboard.bottom))
            insets
        }
        setContentView(root)
        settings.open(savedInstanceState?.getString("stage_page") ?: intent.getStringExtra("stage_page") ?: "home")
        onBackPressedDispatcher.addCallback(this, object : OnBackPressedCallback(true) {
            override fun handleOnBackPressed() {
                if (!settings.back()) { isEnabled = false; onBackPressedDispatcher.onBackPressed() }
            }
        })
        ViewCompat.requestApplyInsets(root)
    }
    override fun onResume() {
        super.onResume()
        LauncherIconManager.onAppOpened(this)
        if (::settings.isInitialized) settings.refresh()
        showUpdatePrompt()
        UpdateCoordinator.maybeCheck(this) {
            if (::settings.isInitialized) settings.open(settings.page)
            showUpdatePrompt()
        }
    }
    private var promptedCode = 0L
    private fun showUpdatePrompt() {
        if (!UpdateCoordinator.auto(this) || isFinishing || isDestroyed) return
        val release = UpdateCoordinator.available(this) ?: return
        if (promptedCode >= release.metadata.versionCode) return
        promptedCode = release.metadata.versionCode
        com.google.android.material.dialog.MaterialAlertDialogBuilder(this)
            .setTitle("发现台前调度 ${release.version}")
            .setMessage(release.notes.ifBlank { "有经过身份校验的新版本可用。" }.take(2000))
            .setNegativeButton("稍后", null)
            .setPositiveButton("查看并安装") { _, _ -> settings.open("about") }.show()
    }
    override fun onNewIntent(intent: android.content.Intent) {
        super.onNewIntent(intent)
        setIntent(intent)
        intent.getStringExtra("stage_page")?.let { if (::settings.isInitialized) settings.open(it) }
    }
    override fun onRequestPermissionsResult(requestCode: Int, permissions: Array<out String>, grantResults: IntArray) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        if (requestCode == 72) UpdateCoordinator.onNotificationPermission(this)
    }
    override fun onSaveInstanceState(outState: Bundle) {
        outState.putString("stage_page", settings.page)
        super.onSaveInstanceState(outState)
    }
}
